import React, { Component } from 'react';
import { Link } from 'react-router-dom';
import styles from './InventoryManager.module.css';

class InventoryManager extends Component {
    constructor(props) {
        super(props);
        this.state = {
            products: [],
            loading: true,
            stats: null,
            lowStockProducts: [],
            filter: 'all', // all, low, out, normal
            sortBy: 'stockQuantity',
            sortOrder: 'asc',
            selectedProduct: null,
            editQuantity: '',
            showEditModal: false,
            updating: false
        };

        // Привязываем методы
        this.fetchProducts = this.fetchProducts.bind(this);
        this.handleFilterChange = this.handleFilterChange.bind(this);
        this.handleSortChange = this.handleSortChange.bind(this);
        this.handleEditClick = this.handleEditClick.bind(this);
        this.handleQuantityChange = this.handleQuantityChange.bind(this);
        this.handleUpdateQuantity = this.handleUpdateQuantity.bind(this);
        this.handleCloseModal = this.handleCloseModal.bind(this);
        this.handleLowStockAlert = this.handleLowStockAlert.bind(this);
        this.handleRestockAll = this.handleRestockAll.bind(this);
        this.calculateStats = this.calculateStats.bind(this);
    }

    componentDidMount() {
        this.fetchProducts();

        // Обновляем каждые 5 минут
        this.interval = setInterval(() => {
            this.fetchProducts();
        }, 5 * 60 * 1000);
    }

    componentWillUnmount() {
        if (this.interval) {
            clearInterval(this.interval);
        }
    }

    async fetchProducts() {
        try {
            this.setState({ loading: true });
            const response = await fetch('http://localhost:5000/api/products?limit=100');
            const data = await response.json();

            if (data.success) {
                const products = data.data.products || [];
                this.setState({
                    products,
                    loading: false
                }, () => {
                    // После загрузки рассчитываем статистику
                    this.calculateStats(products);
                });
            }
        } catch (error) {
            console.error('Error fetching products:', error);
            this.setState({ loading: false });
        }
    }

    calculateStats(products) {
        const totalProducts = products.length;
        const totalStock = products.reduce((sum, p) => sum + p.stockQuantity, 0);
        const lowStock = products.filter(p => p.stockQuantity < p.minStockLevel);
        const outOfStock = products.filter(p => p.stockQuantity === 0);
        const inStock = products.filter(p => p.stockQuantity > 0);

        const lowStockValue = lowStock.reduce((sum, p) => sum + (p.currentPrice * (p.minStockLevel - p.stockQuantity)), 0);
        const totalValue = products.reduce((sum, p) => sum + (p.currentPrice * p.stockQuantity), 0);

        this.setState({
            stats: {
                totalProducts,
                totalStock,
                lowStockCount: lowStock.length,
                outOfStockCount: outOfStock.length,
                inStockCount: inStock.length,
                lowStockValue,
                totalValue
            },
            lowStockProducts: lowStock
        });
    }

    handleFilterChange(filter) {
        this.setState({ filter });
    }

    handleSortChange(sortBy) {
        this.setState(prevState => ({
            sortBy,
            sortOrder: prevState.sortBy === sortBy ?
                (prevState.sortOrder === 'asc' ? 'desc' : 'asc') : 'asc'
        }));
    }

    handleEditClick(product) {
        this.setState({
            selectedProduct: product,
            editQuantity: product.stockQuantity.toString(),
            showEditModal: true
        });
    }

    handleQuantityChange(e) {
        this.setState({ editQuantity: e.target.value });
    }

    async handleUpdateQuantity() {
        const { selectedProduct, editQuantity } = this.state;
        const token = localStorage.getItem('token');

        if (!selectedProduct || !editQuantity) return;

        const quantity = parseInt(editQuantity);
        if (isNaN(quantity) || quantity < 0) return;

        this.setState({ updating: true });

        try {
            const response = await fetch(`http://localhost:5000/api/products/${selectedProduct._id}`, {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify({
                    stockQuantity: quantity,
                    inStock: quantity > 0
                })
            });

            const data = await response.json();

            if (data.success) {
                // Обновляем локальное состояние
                this.setState(prevState => ({
                    products: prevState.products.map(p =>
                        p._id === selectedProduct._id
                            ? { ...p, stockQuantity: quantity, inStock: quantity > 0 }
                            : p
                    ),
                    showEditModal: false,
                    selectedProduct: null,
                    editQuantity: '',
                    updating: false
                }), () => {
                    this.calculateStats(this.state.products);
                    alert('Количество успешно обновлено!');
                });
            } else {
                alert(data.message || 'Ошибка обновления');
                this.setState({ updating: false });
            }
        } catch (error) {
            console.error('Error updating quantity:', error);
            alert('Ошибка подключения к серверу');
            this.setState({ updating: false });
        }
    }

    handleCloseModal() {
        this.setState({
            showEditModal: false,
            selectedProduct: null,
            editQuantity: ''
        });
    }

    handleLowStockAlert(product) {
        alert(`Товар "${product.name}" требует пополнения!\nТекущий остаток: ${product.stockQuantity} шт.\nМинимальный уровень: ${product.minStockLevel} шт.\nНеобходимо докупить: ${product.minStockLevel - product.stockQuantity} шт.`);
    }

    async handleRestockAll() {
        if (!confirm('Вы уверены, что хотите автоматически пополнить все товары с низким запасом до минимального уровня?')) return;

        const token = localStorage.getItem('token');
        const { lowStockProducts } = this.state;

        for (const product of lowStockProducts) {
            try {
                const response = await fetch(`http://localhost:5000/api/products/${product._id}`, {
                    method: 'PUT',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': `Bearer ${token}`
                    },
                    body: JSON.stringify({
                        stockQuantity: product.minStockLevel,
                        inStock: true
                    })
                });

                const data = await response.json();
                if (!data.success) {
                    console.error(`Failed to restock ${product.name}:`, data.message);
                }
            } catch (error) {
                console.error(`Error restocking ${product.name}:`, error);
            }
        }

        // Обновляем список
        setTimeout(() => {
            this.fetchProducts();
            alert('Пополнение запущено! Данные обновятся через несколько секунд.');
        }, 1000);
    }

    getFilteredProducts() {
        const { products, filter, sortBy, sortOrder } = this.state;

        let filtered = [...products];

        switch (filter) {
            case 'low':
                filtered = filtered.filter(p => p.stockQuantity < p.minStockLevel && p.stockQuantity > 0);
                break;
            case 'out':
                filtered = filtered.filter(p => p.stockQuantity === 0);
                break;
            case 'normal':
                filtered = filtered.filter(p => p.stockQuantity >= p.minStockLevel);
                break;
            // 'all' - оставляем все
        }

        // Сортировка
        filtered.sort((a, b) => {
            let aValue = a[sortBy];
            let bValue = b[sortBy];

            // Особые случаи
            if (sortBy === 'stockLevelPercentage') {
                aValue = (a.stockQuantity / a.minStockLevel) * 100;
                bValue = (b.stockQuantity / b.minStockLevel) * 100;
            }

            if (sortOrder === 'asc') {
                return aValue > bValue ? 1 : -1;
            } else {
                return aValue < bValue ? 1 : -1;
            }
        });

        return filtered;
    }

    renderStats() {
        const { stats } = this.state;
        if (!stats) return null;

        return (
            <div className={styles.statsGrid}>
                <div className={styles.statCard}>
                    <div className={styles.statIcon}>📊</div>
                    <div className={styles.statContent}>
                        <h3>Всего товаров</h3>
                        <p className={styles.statNumber}>{stats.totalProducts}</p>
                        <p className={styles.statLabel}>в системе</p>
                    </div>
                </div>

                <div className={styles.statCard}>
                    <div className={styles.statIcon}>📦</div>
                    <div className={styles.statContent}>
                        <h3>Общий остаток</h3>
                        <p className={styles.statNumber}>{stats.totalStock}</p>
                        <p className={styles.statLabel}>единиц на складе</p>
                    </div>
                </div>

                <div className={styles.statCard}>
                    <div className={styles.statIcon}>⚠️</div>
                    <div className={styles.statContent}>
                        <h3>Низкий запас</h3>
                        <p className={styles.statNumber}>{stats.lowStockCount}</p>
                        <p className={styles.statLabel}>требуют пополнения</p>
                    </div>
                </div>

                <div className={styles.statCard}>
                    <div className={styles.statIcon}>💰</div>
                    <div className={styles.statContent}>
                        <h3>Стоимость запасов</h3>
                        <p className={styles.statNumber}>{stats.totalValue.toFixed(2)}</p>
                        <p className={styles.statLabel}>BYN на складе</p>
                    </div>
                </div>
            </div>
        );
    }

    renderProductsTable() {
        const { filter, sortBy, sortOrder } = this.state;
        const products = this.getFilteredProducts();

        if (products.length === 0) {
            return (
                <div className={styles.emptyState}>
                    <p>Нет товаров, соответствующих выбранному фильтру</p>
                </div>
            );
        }

        return (
            <div className={styles.tableContainer}>
                <table className={styles.productsTable}>
                    <thead>
                    <tr>
                        <th>Товар</th>
                        <th>Артикул</th>
                        <th>Категория</th>
                        <th
                            className={styles.sortable}
                            onClick={() => this.handleSortChange('stockQuantity')}
                        >
                            Остаток
                            {sortBy === 'stockQuantity' && (
                                <span className={styles.sortIndicator}>
                                        {sortOrder === 'asc' ? '↑' : '↓'}
                                    </span>
                            )}
                        </th>
                        <th>Мин. уровень</th>
                        <th>Уровень запаса</th>
                        <th>Цена</th>
                        <th>Действия</th>
                    </tr>
                    </thead>
                    <tbody>
                    {products.map(product => {
                        const stockPercentage = (product.stockQuantity / product.minStockLevel) * 100;
                        const isLowStock = product.stockQuantity < product.minStockLevel;
                        const isOutOfStock = product.stockQuantity === 0;

                        let stockLevelClass = '';
                        let stockLevelText = '';

                        if (isOutOfStock) {
                            stockLevelClass = styles.outOfStock;
                            stockLevelText = 'Нет в наличии';
                        } else if (isLowStock) {
                            stockLevelClass = styles.lowStock;
                            stockLevelText = 'Низкий запас';
                        } else {
                            stockLevelClass = styles.normalStock;
                            stockLevelText = 'Норма';
                        }

                        return (
                            <tr key={product._id} className={stockLevelClass}>
                                <td>
                                    <div className={styles.productCell}>
                                        <img
                                            src={product.imageUrl}
                                            alt={product.name}
                                            className={styles.productImage}
                                        />
                                        <div>
                                            <strong>{product.name}</strong>
                                            <div className={styles.animalTypes}>
                                                {product.animalType?.join(', ')}
                                            </div>
                                        </div>
                                    </div>
                                </td>
                                <td>
                                    <code>{product.sku}</code>
                                </td>
                                <td>{product.category}</td>
                                <td>
                                    <div className={styles.stockQuantity}>
                                            <span className={styles.quantityNumber}>
                                                {product.stockQuantity} шт.
                                            </span>
                                        {isLowStock && !isOutOfStock && (
                                            <span className={styles.required}>
                                                    Нужно: {product.minStockLevel - product.stockQuantity} шт.
                                                </span>
                                        )}
                                    </div>
                                </td>
                                <td>{product.minStockLevel} шт.</td>
                                <td>
                                    <div className={styles.stockLevel}>
                                        <div className={styles.stockBarContainer}>
                                            <div
                                                className={styles.stockBar}
                                                style={{
                                                    width: `${Math.min(stockPercentage, 100)}%`,
                                                    backgroundColor: isOutOfStock ? '#f56565' :
                                                        isLowStock ? '#ed8936' : '#48bb78'
                                                }}
                                            ></div>
                                        </div>
                                        <span className={styles.stockLevelText}>{stockLevelText}</span>
                                        <span className={styles.stockPercentage}>
                                                ({stockPercentage.toFixed(0)}%)
                                            </span>
                                    </div>
                                </td>
                                <td>{product.currentPrice} BYN</td>
                                <td>
                                    <div className={styles.actionButtons}>
                                        <button
                                            onClick={() => this.handleEditClick(product)}
                                            className={styles.editBtn}
                                        >
                                            Изменить
                                        </button>
                                        {isLowStock && !isOutOfStock && (
                                            <button
                                                onClick={() => this.handleLowStockAlert(product)}
                                                className={styles.alertBtn}
                                            >
                                                ⚠️
                                            </button>
                                        )}
                                        <Link
                                            to={`/products/${product._id}`}
                                            className={styles.detailsBtn}
                                        >
                                            Подробнее
                                        </Link>
                                    </div>
                                </td>
                            </tr>
                        );
                    })}
                    </tbody>
                </table>
            </div>
        );
    }

    renderEditModal() {
        const { selectedProduct, editQuantity, showEditModal, updating } = this.state;

        if (!showEditModal || !selectedProduct) return null;

        return (
            <div className={styles.modalOverlay}>
                <div className={styles.modal}>
                    <div className={styles.modalHeader}>
                        <h3>Изменение остатка товара</h3>
                        <button
                            onClick={this.handleCloseModal}
                            className={styles.closeBtn}
                        >
                            ×
                        </button>
                    </div>

                    <div className={styles.modalContent}>
                        <div className={styles.productInfo}>
                            <img
                                src={selectedProduct.imageUrl}
                                alt={selectedProduct.name}
                                className={styles.modalProductImage}
                            />
                            <div>
                                <h4>{selectedProduct.name}</h4>
                                <p>Артикул: <code>{selectedProduct.sku}</code></p>
                                <p>Категория: {selectedProduct.category}</p>
                                <p>Текущий остаток: <strong>{selectedProduct.stockQuantity} шт.</strong></p>
                                <p>Минимальный уровень: {selectedProduct.minStockLevel} шт.</p>
                            </div>
                        </div>

                        <div className={styles.quantityInput}>
                            <label>Новое количество:</label>
                            <input
                                type="number"
                                value={editQuantity}
                                onChange={this.handleQuantityChange}
                                min="0"
                                step="1"
                                disabled={updating}
                            />
                            <small>Введите новое количество товара на складе</small>
                        </div>

                        <div className={styles.modalActions}>
                            <button
                                onClick={this.handleCloseModal}
                                className={styles.cancelModalBtn}
                                disabled={updating}
                            >
                                Отмена
                            </button>
                            <button
                                onClick={this.handleUpdateQuantity}
                                className={styles.saveModalBtn}
                                disabled={updating}
                            >
                                {updating ? 'Сохранение...' : 'Сохранить'}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    render() {
        const { loading, filter, lowStockProducts } = this.state;

        if (loading) {
            return <div className={styles.loading}>Загрузка данных инвентаря...</div>;
        }

        return (
            <div className={styles.inventoryManager}>
                <div className={styles.header}>
                    <h2>Управление складскими запасами 📦</h2>
                    <p>Мониторинг и управление остатками товаров на складе</p>
                </div>

                {this.renderStats()}

                <div className={styles.controls}>
                    <div className={styles.filterControls}>
                        <button
                            className={`${styles.filterBtn} ${filter === 'all' ? styles.active : ''}`}
                            onClick={() => this.handleFilterChange('all')}
                        >
                            Все товары
                        </button>
                        <button
                            className={`${styles.filterBtn} ${filter === 'low' ? styles.active : ''}`}
                            onClick={() => this.handleFilterChange('low')}
                        >
                            Низкий запас
                        </button>
                        <button
                            className={`${styles.filterBtn} ${filter === 'out' ? styles.active : ''}`}
                            onClick={() => this.handleFilterChange('out')}
                        >
                            Нет в наличии
                        </button>
                        <button
                            className={`${styles.filterBtn} ${filter === 'normal' ? styles.active : ''}`}
                            onClick={() => this.handleFilterChange('normal')}
                        >
                            Нормальный запас
                        </button>
                    </div>

                    <div className={styles.actionControls}>
                        {lowStockProducts.length > 0 && (
                            <button
                                onClick={this.handleRestockAll}
                                className={styles.restockAllBtn}
                            >
                                Пополнить все ({lowStockProducts.length})
                            </button>
                        )}

                        <button
                            onClick={this.fetchProducts}
                            className={styles.refreshBtn}
                        >
                            Обновить данные
                        </button>
                    </div>
                </div>

                {this.renderProductsTable()}

                {this.renderEditModal()}
            </div>
        );
    }
}

export default InventoryManager;
